     3	import java.math.BigDecimal;
     4	import shop.domain.DomainException;
     5	import shop.domain.ErrorCode;
     6	
     7	/** Entrega cotada na transportadora (econômica e expressa). */
     8	public class CarrierShipping implements ShippingOption {
     9	    private final String code;
    10	    private final String carrierService;
    11	    private final CarrierClient client;
    12	
    13	    public CarrierShipping(String code, String carrierService, CarrierClient client) {
    14	        this.code = code;
    15	        this.carrierService = carrierService;
    16	        this.client = client;
    17	    }
    18	
    19	    @Override
    20	    public String code() {
    21	        return code;
    22	    }
    23	
    24	    @Override
    25	    public ShippingQuote quote(ShippingRequest request) {
    26	        long grams = request.weightKg().movePointRight(3).longValue();
    27	        try {
    28	            CarrierClient.CarrierQuote quote = client.quote(request.zipCode(), grams, carrierService);
    29	            int days = (quote.etaHours() + 23) / 24 + request.region().extraCarrierDays();
    30	            return new ShippingQuote(new BigDecimal(quote.priceCents()).movePointLeft(2), days);
    31	        } catch (CarrierClient.ZipNotServedException e) {
    32	            throw new DomainException(ErrorCode.SHIPPING_METHOD_UNAVAILABLE);
    33	        } catch (CarrierClient.CarrierDownException e) {
    34	            throw new DomainException(ErrorCode.CARRIER_UNAVAILABLE);
    35	        }
    36	    }
    37	
    38	    @Override
    39	    public boolean chargesFreight() {
    40	        return true;
    41	    }
    42	
    43	    @Override
    44	    public boolean clubWaivable() {
    45	        return true;
    46	    }
    47	}
